fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // No splitting allowed
            result.push(vec![s]);
        } else {
            // Use rsplitn for right-split with limit
            // rsplitn returns at most maxsplit+1 pieces
            let parts: Vec<String> = s.rsplitn((maxsplit as usize) + 1, &sep)
                .map(|part| part.to_string())
                .collect();
            
            // rsplitn returns parts in reverse order (from right to left),
            // so we need to reverse them back
            let mut parts_rev: Vec<String> = parts.into_iter().rev().collect();
            
            // Ensure we have at least one element (even for empty string)
            if parts_rev.is_empty() {
                parts_rev.push(String::new());
            }
            
            result.push(parts_rev);
        }
    }
    
    result
}